//! Fast hashing for integer voxel and chunk coordinates.
//!
//! `std`'s default SipHash resists collision attacks from untrusted input, which
//! coordinates generated by the engine never are. On `IVec3` keys it was a large
//! share of every water step: a single transfer touches the resident-chunk,
//! water-level, velocity, sandbox and activity maps several times each.
//!
//! This is the multiply-rotate hash used by `rustc` (rustc-hash 2.x), inlined to
//! avoid a dependency.

use std::collections::{HashMap, HashSet};
use std::hash::{BuildHasherDefault, Hasher};

pub type FastBuild = BuildHasherDefault<FxHasher>;
pub type FastMap<K, V> = HashMap<K, V, FastBuild>;
pub type FastSet<K> = HashSet<K, FastBuild>;

const K: u64 = 0xf135_7aea_2e62_a9c5;

#[derive(Default, Clone, Copy)]
pub struct FxHasher {
    hash: u64,
}

impl FxHasher {
    #[inline]
    fn add(&mut self, word: u64) {
        self.hash = self.hash.wrapping_add(word).wrapping_mul(K);
    }
}

impl Hasher for FxHasher {
    #[inline]
    fn write(&mut self, bytes: &[u8]) {
        let mut chunks = bytes.chunks_exact(8);
        for chunk in &mut chunks {
            self.add(u64::from_le_bytes(chunk.try_into().unwrap()));
        }
        let rest = chunks.remainder();
        if !rest.is_empty() {
            let mut word = [0u8; 8];
            word[..rest.len()].copy_from_slice(rest);
            self.add(u64::from_le_bytes(word));
        }
    }
    #[inline]
    fn write_u8(&mut self, i: u8) {
        self.add(i as u64);
    }
    #[inline]
    fn write_u16(&mut self, i: u16) {
        self.add(i as u64);
    }
    #[inline]
    fn write_u32(&mut self, i: u32) {
        self.add(i as u64);
    }
    #[inline]
    fn write_u64(&mut self, i: u64) {
        self.add(i);
    }
    #[inline]
    fn write_usize(&mut self, i: usize) {
        self.add(i as u64);
    }
    #[inline]
    fn write_i32(&mut self, i: i32) {
        self.add(i as u32 as u64);
    }
    #[inline]
    fn finish(&self) -> u64 {
        // hashbrown picks buckets from the low bits and tags from the high
        // bits; the rotate mixes the multiply's well-spread high bits into both.
        self.hash.rotate_left(26)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use glam::IVec3;

    #[test]
    fn neighbouring_coordinates_spread_across_buckets() {
        // A 16^3 block of adjacent cells must not pile into a few low-bit buckets.
        let mut buckets = [0u32; 256];
        for x in 0..16 {
            for y in 0..16 {
                for z in 0..16 {
                    let mut h = FxHasher::default();
                    std::hash::Hash::hash(&IVec3::new(x, y, z), &mut h);
                    buckets[(h.finish() & 255) as usize] += 1;
                }
            }
        }
        let worst = *buckets.iter().max().unwrap();
        assert!(worst < 48, "worst bucket holds {worst} of 4096 (ideal 16)");
    }
}
